// Arbeitsliste als HTML-Seite. Werte werden escaped, weil Mailtexte von außen kommen.
// Kein CSS-Framework und keine Schrift von fremden Servern: Die Seite zeigt vertrauliche Preise und soll auch ohne Internet laufen.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const reviews = $('Offene Reviews laden').all().map((i) => i.json).filter((r) => r.id);
const aufgaben = $('Offene Aufgaben laden').all().map((i) => i.json).filter((a) => a.id);
const k = $('Kennzahlen und Audit laden').first().json;
const historie = $('Historie laden').all().map((i) => i.json).filter((h) => h.mail_domain);
const e = k.einstellungen ?? {};

// Anonyme Ansicht für Screenshots (?anonym=1): Der Server ersetzt die Daten, bevor die Seite den Browser erreicht.
// Ein Skript, das erst im Browser maskiert, ließe die echten Werte im Quelltext stehen und übersieht leicht Freitext.
// Deshalb fallen Mailtexte, Betreffs, Zusammenfassungen und Antwortentwürfe hier ganz weg.
const anonym = String($('Webhook Arbeitsliste').first().json.query?.anonym ?? '') === '1';
const pseudonym = (bilde) => {
  const vergeben = new Map();
  return (wert) => {
    if (wert === null || wert === undefined || wert === '') return '–';
    if (!anonym) return esc(wert);
    if (!vergeben.has(wert)) vergeben.set(wert, bilde(vergeben.size));
    return `<span class="maske">${vergeben.get(wert)}</span>`;
  };
};
const lieferant = pseudonym((i) => `[LIEFERANT_${String.fromCharCode(65 + (i % 26))}${i >= 26 ? Math.floor(i / 26) : ''}]`);
const nummer = pseudonym((i) => `ID-${String(i + 1).padStart(3, '0')}`);
const person = pseudonym((i) => `[MITARBEITER_${i + 1}]`);
const AUSGEBLENDET = '<span class="maske">[ausgeblendet]</span>';

// Zahlen immer in Monospace. Beträge sind im Screenshot-Modus maskiert, Prozentwerte und Daten bleiben sichtbar.
const de = (n, stellen = 2) => Number(n).toLocaleString('de-DE', { minimumFractionDigits: stellen, maximumFractionDigits: stellen });
const zahl = (n) => `<span class="num">${Number(n).toLocaleString('de-DE', { maximumFractionDigits: 4 })}</span>`;
const betrag = (n, waehrung = 'EUR') => (anonym ? '<span class="maske num">***,** €</span>'
  : `<span class="num">${de(n)}&nbsp;${waehrung === 'EUR' ? '€' : esc(waehrung)}</span>`);
const prozent = (n) => `<span class="num">${Number(n) > 0 ? '+' : ''}${Number(n).toLocaleString('de-DE', { maximumFractionDigits: 1 })}&nbsp;%</span>`;
const datum = (d) => (d ? `<span class="num">${(typeof d === 'string' ? d : new Date(d).toISOString()).slice(0, 10).split('-').reverse().join('.')}</span>` : '–');

// Micro-Icons als Inline-SVG, Farbe kommt über currentColor aus dem Badge
const ICON = {
  punkt: '<svg viewBox="0 0 8 8" class="i"><circle cx="4" cy="4" r="3" fill="currentColor"/></svg>',
  haken: '<svg viewBox="0 0 16 16" class="i"><path d="M3.5 8.5l3 3 6-7" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  warnung: '<svg viewBox="0 0 16 16" class="i"><path d="M8 2.2L14.3 13H1.7z" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/><path d="M8 6.5v3" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/><circle cx="8" cy="11.3" r=".8" fill="currentColor"/></svg>',
  kreis: '<svg viewBox="0 0 16 16" class="i"><circle cx="8" cy="8" r="5.5" fill="none" stroke="currentColor" stroke-width="1.4"/></svg>',
  info: '<svg viewBox="0 0 16 16" class="i"><circle cx="8" cy="8" r="6.2" fill="none" stroke="currentColor" stroke-width="1.2"/><path d="M8 7.2v4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/><circle cx="8" cy="5" r=".85" fill="currentColor"/></svg>',
  ziel: '<svg viewBox="0 0 16 16" class="i"><circle cx="8" cy="8" r="6" fill="none" stroke="currentColor" stroke-width="1.3"/><circle cx="8" cy="8" r="3" fill="none" stroke="currentColor" stroke-width="1.3"/><circle cx="8" cy="8" r="1" fill="currentColor"/></svg>',
  flamme: '<svg viewBox="0 0 16 16" class="i"><path d="M8 1.8c.6 2.2 3.6 3.6 3.6 7a3.6 3.6 0 01-7.2 0c0-1.5.7-2.5 1.5-3.3.1 1 .6 1.7 1.3 2 .1-2.2.3-3.9.8-5.7z" fill="currentColor"/></svg>',
  blitz: '<svg viewBox="0 0 16 16" class="i"><path d="M9.2 1.5L3.5 9h3.8l-.9 5.5L12.5 7H8.6z" fill="currentColor"/></svg>',
  stern: '<svg viewBox="0 0 16 16" class="i"><path d="M8 1.8l1.8 3.9 4.2.5-3.1 2.9.8 4.2L8 11.2l-3.7 2.1.8-4.2L2 6.2l4.2-.5z" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round"/></svg>',
  pfeil: '<svg viewBox="0 0 16 16" class="i"><path d="M3 8h9M8.5 4.5L12 8l-3.5 3.5" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  puls: '<svg viewBox="0 0 24 24" class="i logo"><rect x="1" y="1" width="22" height="22" rx="6" fill="#0f172a"/><path d="M4.5 12.5h4l2-5 3 9 2-4h4" fill="none" stroke="#5eead4" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  schloss: '<svg viewBox="0 0 16 16" class="i"><rect x="3" y="7" width="10" height="7" rx="1.5" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M5.5 7V5a2.5 2.5 0 015 0v2" fill="none" stroke="currentColor" stroke-width="1.4"/></svg>',
  offen: '<svg viewBox="0 0 16 16" class="i"><rect x="3" y="7" width="10" height="7" rx="1.5" fill="none" stroke="currentColor" stroke-width="1.4"/><path d="M5.5 7V5a2.5 2.5 0 014.9-.6" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>',
};
ICON.funke = '<svg viewBox="0 0 16 16" class="i"><path d="M8 1.5l1.4 3.6 3.6 1.4-3.6 1.4L8 11.5 6.6 7.9 3 6.5l3.6-1.4z" fill="currentColor"/><path d="M12.5 10.5l.6 1.4 1.4.6-1.4.6-.6 1.4-.6-1.4-1.4-.6 1.4-.6z" fill="currentColor"/></svg>';
const badge = (ton, text, puls = false) => `<span class="badge ${ton}">${puls ? '<span class="puls"></span>' : ICON[{ krit: 'warnung', warn: 'kreis', ok: 'haken', neutral: 'punkt' }[ton]]}${esc(text)}</span>`;
// Regelbegründung als Tooltip: zeigt, welche Regel mit welchen Werten entschieden hat
const regel = (text) => (text ? `<span class="tip" tabindex="0" aria-label="${esc(text)}" data-tip="${esc(text)}">${ICON.info}</span>` : '');
const befund = (ton, html, regeltext) => `<li class="befund ${ton}">${ICON[{ krit: 'warnung', warn: 'kreis', ok: 'haken', neutral: 'punkt' }[ton]]}<span>${html}</span>${regel(regeltext)}</li>`;
// Geschütztes Leerzeichen, damit Zahl und Einheit nicht umbrechen (auch in Tooltips, deshalb kein &nbsp;)
const pz = (n) => `${Number(n).toLocaleString('de-DE', { maximumFractionDigits: 1 })} %`;
const eur = (n) => `${Number(n).toLocaleString('de-DE')} €`;

// Befunde je Aufgabe: was das System festgestellt hat und nach welcher Regel
const TERMIN = {
  termin_unsicher: (a) => [`Termin unsicher, gewünscht ${datum(a.gewuenscht)}`, 'Lieferant nennt den Termin nur voraussichtlich oder ohne Gewähr'],
  termin_fehlt: (a) => [`Kein Termin bestätigt, gewünscht ${datum(a.gewuenscht)}`, 'Die AB enthält keinen konkreten Liefertermin'],
  termin_spaeter: (a) => [`Termin ${datum(a.gewuenscht)} → ${datum(a.bestaetigt)}`, 'Bestätigter Termin liegt nach dem Wunschtermin der Bestellung'],
};
const PRUEFGRUND = {
  liefertreue_unter_schwelle: (ab) => [`Liefertreue <span class="num">${esc(ab.liefertreue)}&nbsp;%</span> unter Schwelle`,
    `System-Flag: Liefertreue ${ab.liefertreue} % < Schwellenwert ${ab.schwelle} % (${ab.abc_xyz}-Artikel)`],
  blindbestaetigung_verdacht: (ab) => [`AB nach <span class="num">${esc(ab.bearbeitungszeit_minuten)}</span> Minuten: Blindbestätigung?`,
    `System-Flag: Bearbeitungszeit ${ab.bearbeitungszeit_minuten} min < ${e.blindbestaetigung_minuten ?? 30} min nach Bestellversand`],
  neuer_lieferant: () => ['Neuer Lieferant: Kontakt aufnehmen und Termin absichern', 'System-Flag: Lieferant ohne Liefertreue-Historie'],
  absender_domain_abweichend: () => ['Absender-Domain passt nicht zum Lieferanten', 'System-Flag: Domain des Absenders weicht von der Domain in den Stammdaten ab'],
};
const preisBefunde = (d) => {
  const b = [];
  if (d.angabe_lieferant_prozent != null) {
    b.push(befund('warn', `Lieferant nennt ${prozent(d.angabe_lieferant_prozent)}, gerechnet ${prozent(d.prozent)}`,
      'System-Flag: Angabe des Lieferanten weicht um mehr als 0,5 Prozentpunkte von Bestell- und AB-Preis ab'));
  }
  if ((d.alter_preis_gilt ?? []).length) {
    b.push(befund('warn', `Zum alten Preis bestätigt: ${d.alter_preis_gilt.map(nummer).join(', ')}. Alter Preis gilt, Rechnung prüfen`,
      'System-Flag: Bestätigung des Lieferanten liegt vor dem Eingang der Mitteilung, der vereinbarte Preis gilt'));
  }
  if (d.jahresbedarf_fehlt === true || (Array.isArray(d.jahresbedarf_fehlt) && d.jahresbedarf_fehlt.length)) {
    b.push(befund('warn', `Jahresbedarf fehlt${Array.isArray(d.jahresbedarf_fehlt) ? ` für ${esc(d.jahresbedarf_fehlt.join(', '))}` : ''}`,
      'Ohne Jahresbedarf lässt sich der Full-Year-Effekt nicht berechnen. Er wird nicht als 0 € gezählt.'));
  }
  const letzte = d.letzte_aenderung ?? d.letzte_erhoehung;
  if (letzte) b.push(befund('neutral', `Letzte Erhöhung ${datum(letzte.gueltig_ab)}: ${prozent(letzte.prozent)}`, 'Quelle: Tabelle preis_historie'));
  if (d.prozent_12_monate != null) {
    b.push(befund(d.prozent_12_monate > Number(e.preis_toleranz_dispo_prozent ?? 5) ? 'warn' : 'neutral',
      `Zwölf Monate zusammen: ${prozent(d.prozent_12_monate)}`, 'Neuer Preis gegen den Preis, der vor zwölf Monaten galt'));
  }
  return b;
};
const befunde = (a) => {
  const d = a.details ?? {};
  const b = [];
  if (a.art === 'eskalation') {
    for (const g of d.eskalation ?? []) {
      if (g === 'jahres_mehrkosten') {
        const grenze = a.team === 'Geschäftsleitung' ? e.eskalation_geschaeftsleitung_euro : e.eskalation_einkaufsleitung_euro;
        b.push(befund('krit', `Jahreswirkung über der Freigabegrenze von <span class="num">${esc(eur(grenze))}</span>`,
          `System-Flag: Full-Year-Effekt ${anonym ? '***' : eur(d.jahres_mehrkosten_eur)} ≥ Schwellenwert ${eur(grenze)}`));
      }
      if (g === 'liefertreue_und_preis') {
        b.push(befund('krit', 'Hohe Erhöhung bei schwacher Liefertreue: Alternativlieferant prüfen',
          `System-Flag: Liefertreue ${pz(d.liefertreue)} < ${pz(e.eskalation_liefertreue_prozent)} und Erhöhung ${pz(d.prozent)} > ${pz(e.eskalation_liefertreue_preis_prozent)}`));
      }
    }
  }
  if (a.art === 'preis_freigeben') {
    b.push(befund('ok', 'Innerhalb der Freigabegrenze der Disposition',
      `Regel: Erhöhung ${pz(d.prozent)} ≤ ${pz(e.preis_toleranz_dispo_prozent)}, Mehrkosten ≤ ${eur(e.preis_toleranz_dispo_euro)} je Bestellung und Jahreswirkung < ${eur(e.eskalation_einkaufsleitung_euro)}`));
  }
  if (a.art === 'preiserhoehung_pruefen') {
    b.push(befund(a.prioritaet === 'hoch' ? 'warn' : 'neutral', a.prioritaet === 'hoch' ? 'Über der Freigabegrenze der Disposition' : 'Unter der Freigabegrenze, Entscheidung beim Einkäufer',
      `Regel: Hohe Priorität ab Erhöhung > ${pz(e.preis_toleranz_dispo_prozent)}, Mehrkosten > ${eur(e.preis_toleranz_dispo_euro)} oder Jahreswirkung ≥ ${eur(e.eskalation_einkaufsleitung_euro)}`));
  }
  if (a.art === 'preis_info' && a.team === 'Strategischer Einkauf') {
    b.push(befund('neutral', 'Info an den strategischen Einkauf', `Regel: Erhöhung ≥ ${pz(e.preis_eskalation_strategie_prozent)}`));
  }
  if (['eskalation', 'preis_freigeben', 'preiserhoehung_pruefen', 'preis_info'].includes(a.art)) b.push(...preisBefunde(d));
  // Merker von Modell und Regel: Technik, QM, Disposition. Nur Vorschlag, eingebunden wird per Knopf.
  const ab = a.abteilungen ?? {};
  const betroffen = ['technik', 'qm', 'dispo'].filter((x) => ab[x]);
  if (betroffen.length && !['technik_freigabe', 'qm_freigabe', 'bestand_pruefen', 'entwurf_senden'].includes(a.art)) {
    const namen = { technik: 'Technik', qm: 'QM', dispo: 'Disposition' };
    const quelle = [ab.modell?.length ? `Modell: ${ab.modell.map((x) => namen[x]).join(', ')}` : null,
      ab.regel?.length ? `Regel: ${ab.regel.join(', ')}` : null].filter(Boolean).join(' · ');
    const werkstoff = ab.werkstoff_alt || ab.werkstoff_neu ? ` (Werkstoff <span class="num">${esc(ab.werkstoff_alt ?? '?')}</span> → <span class="num">${esc(ab.werkstoff_neu ?? '?')}</span>)` : '';
    b.push(befund('krit', `${betroffen.map((x) => namen[x]).join(', ')} erforderlich${werkstoff}`, `System-Flag: ${quelle}. Aufgaben entstehen erst über „Technik & QM einbinden“`));
    if (ab.empfehlung && !anonym) b.push(befund('neutral', `Vorschlag des Modells, ungeprüft: ${esc(ab.empfehlung)}`, 'Freier Text des Sprachmodells, nicht durch Regeln geprüft'));
  }
  if (PREISARTEN.includes(a.art) && gesperrt(a)) {
    b.push(befund('warn', 'Preisfreigabe gesperrt, bis Technik und QM freigegeben haben', 'Regel: Bei Material- oder Werkstoffänderung keine Preisfreigabe ohne Freigabe von Technik und QM (prüft auch der Server)'));
  }
  if (['technik_freigabe', 'qm_freigabe', 'bestand_pruefen'].includes(a.art)) {
    if (d.aenderung) b.push(befund('warn', esc(d.aenderung), 'Aus der Mail des Lieferanten, Werkstoffe per Belegprüfung gegen den Mailtext geprüft'));
    b.push(befund('neutral', {
      technik_freigabe: 'Ist der neue Werkstoff bzw. Nachfolger zulässig? Braucht es eine Zeichnungsänderung?',
      qm_freigabe: 'Erstmusterprüfung, Prüfumfang und Zeugnisse (z. B. 3.1 nach EN 10204) festlegen',
      bestand_pruefen: 'Reichweite des Bestands prüfen, letzte Bestellung im bisherigen Werkstoff nötig?',
    }[a.art], 'Bis zur Freigabe von Technik und QM wird nichts umgestellt'));
    if (d.empfehlung && !anonym) b.push(befund('neutral', `Vorschlag des Modells, ungeprüft: ${esc(d.empfehlung)}`, 'Freier Text des Sprachmodells'));
  }
  if (a.art === 'liefertermin_pruefen') {
    for (const t of d.abweichungen ?? []) { const [text, r] = TERMIN[t.art]?.(t) ?? [esc(t.art), null]; b.push(befund('warn', text, r)); }
  }
  if (a.art === 'ab_klaeren') {
    const ab = a.ab_pruefung ?? {};
    for (const m of d.abweichungen ?? []) {
      if (m.art === 'menge') {
        b.push(befund('warn', `Menge ${zahl(m.bestellt)} → ${zahl(m.bestaetigt)}${m.grund && !anonym ? ` (${esc(m.grund)})` : ''}`, 'Bestätigte Menge weicht von der Bestellung ab'));
        if (m.mehrwert) b.push(befund('neutral', `${m.mehrwert > 0 ? 'Mehrwert' : 'Minderwert'} ${betrag(Math.abs(m.mehrwert), m.waehrung)}`, 'Mengendifferenz × Einzelpreis'));
        if (m.passt_zur_vpe === true) b.push(befund('ok', `Volle Verpackungseinheiten à ${zahl(m.vpe_stamm)}`, `Bestätigte Menge ist ein Vielfaches der VPE ${m.vpe_stamm} aus den Stammdaten`));
        if (m.passt_zur_vpe === false) b.push(befund('warn', `Passt nicht zur VPE ${zahl(m.vpe_stamm)} in den Stammdaten`, `System-Flag: ${m.bestaetigt} ist kein Vielfaches von ${m.vpe_stamm}. Stammdaten oder AB prüfen`));
        if (m.moq_stamm && m.bestellt < m.moq_stamm) b.push(befund('warn', `Bestellung lag unter der Mindestmenge ${zahl(m.moq_stamm)}`, 'Bestellmenge < Mindestbestellmenge laut Stammdaten'));
      } else if (m.art === 'stammdaten_pruefen') {
        b.push(befund('warn', `Stammdaten prüfen${m.hinweis && !anonym ? `: ${esc(m.hinweis)}` : ''}`, 'Lieferant nennt Verpackungseinheit oder Stammdaten als Grund'));
      }
    }
    for (const g of d.pruefgruende ?? []) { const [text, r] = PRUEFGRUND[g]?.(ab) ?? [esc(g), null]; b.push(befund('warn', text, r)); }
  }
  return b;
};

// Kennwerte je Aufgabe als zweispaltiges Datengitter
const gitter = (a) => {
  const d = a.details ?? {};
  const felder = [
    ['Bestellung', a.bestellnummer ? `<span class="num">${nummer(a.bestellnummer)}</span>` : null],
    ['Artikel', a.artikel ? esc(a.artikel) : null],
    ['Zuständig', a.zustaendig ? person(a.zustaendig) : null],
    ['Erhöhung', d.prozent != null ? prozent(d.prozent) + (d.prozent_quelle === 'berechnet' ? ' <span class="leise">berechnet</span>' : '') : null],
    ['Preis', d.art === 'preis' ? `${betrag(d.bestellt, d.waehrung)} → ${betrag(d.bestaetigt, d.waehrung)}` : null],
    ['Mehrkosten', d.mehrkosten != null ? `${betrag(d.mehrkosten, d.waehrung)} <span class="leise">${d.art === 'preis' ? 'diese Bestellung' : `${(d.betroffene_bestellungen ?? []).length} offene Bestellungen`}</span>` : null],
    ['Full-Year-Effekt', d.jahres_mehrkosten_eur != null ? betrag(d.jahres_mehrkosten_eur) : null],
    ['Gültig ab', d.gueltig_ab ? datum(d.gueltig_ab) : null],
    ['Liefertreue', d.liefertreue != null ? `<span class="num">${esc(d.liefertreue)}&nbsp;%</span>` : null],
    ['Termin', a.art === 'liefertermin_pruefen' && d.bestaetigt ? `${datum(d.gewuenscht)} → ${datum(d.bestaetigt)}` : null],
  ].filter(([, wert]) => wert !== null);
  return `<dl class="gitter">${felder.map(([name, wert]) => `<div><dt>${name}</dt><dd>${wert}</dd></div>`).join('')}</dl>`;
};

const KATEGORIE = { auftragsbestaetigung: 'AB', preiserhoehung: 'Preiserhöhung', angebot: 'Angebot', reklamation: 'Reklamation',
  lieferverzug: 'Lieferverzug', rechnung: 'Rechnung', sonstiges: 'Sonstiges' };
const ARTEN = {
  liefertermin_pruefen: 'Liefertermin prüfen', preis_freigeben: 'Preis freigeben', preiserhoehung_pruefen: 'Preiserhöhung prüfen',
  preis_info: 'Info: Preisänderung', ab_klaeren: 'Auftragsbestätigung klären', bearbeiten: 'Bearbeiten', eskalation: 'Preiserhöhung freigeben',
  technik_freigabe: 'Technik-Freigabe', qm_freigabe: 'QM-Freigabe', bestand_pruefen: 'Bestand und letzte Bestellung prüfen',
  entwurf_senden: 'Entwurf prüfen und senden',
};
// Status-Badge: kritisch bei Eskalation oder über 10 %, Warnung bei hoher Priorität, sonst neutral; Infos grün
const status = (a) => {
  const p = a.details?.prozent;
  if (a.art === 'eskalation') return badge('krit', a.team === 'Geschäftsleitung' ? 'Eskalation GL' : 'Eskalation', true);
  if (['technik_freigabe', 'qm_freigabe'].includes(a.art)) return badge('krit', 'Freigabe nötig', true);
  if (a.art === 'entwurf_senden') return badge('neutral', a.details?.art === 'intern' ? 'Entwurf intern' : 'Entwurf Lieferant');
  if (p != null && p > Number(e.preis_eskalation_strategie_prozent ?? 10) && a.status === 'offen') return badge('krit', `> ${pz(e.preis_eskalation_strategie_prozent ?? 10)}`, true);
  if (a.status === 'info') return badge('ok', a.art === 'preis_info' && a.team === 'Einkauf' ? 'Auto-Freigabe' : 'Info');
  if (a.prioritaet === 'hoch') return badge('warn', 'Hohe Priorität');
  if (a.art === 'preis_freigeben') return badge('ok', 'Freigabe Dispo');
  return badge('neutral', 'Offen');
};

// Entscheiden direkt in der Karte. Jede Aktion ist ein POST an /webhook/aufgabe (kein Link: Link-Vorschauen und
// Prefetching dürfen nichts freigeben). Der Server prüft Herkunft, Aktion und Name und schreibt ins Audit-Protokoll.
// Im Screenshot-Modus gibt es keine Aktionen.
const PREISARTEN = ['preis_freigeben', 'preiserhoehung_pruefen', 'eskalation'];
const ENTSCHEIDBAR = [...PREISARTEN, 'technik_freigabe', 'qm_freigabe'];
// Preisfreigabe gesperrt, solange Technik bzw. QM nicht freigegeben haben: sobald sie eingebunden sind oder
// Modell bzw. Regel sie für nötig halten (gleiche Regel wie im Code des Endpunkts und in der Datenbank)
const NAMEN = { technik: 'Technik', qm: 'QM', dispo: 'Disposition' };
const pflicht = (a) => [['technik', 'technik_freigabe'], ['qm', 'qm_freigabe']]
  .filter(([m, art]) => a.abteilungen?.[m] || (a.ticket_aufgaben ?? []).some((y) => y.art === art));
const offenePflicht = (a) => pflicht(a).filter(([, art]) => !(a.ticket_aufgaben ?? []).some((y) => y.art === art && y.entscheidung === 'freigegeben'));
const gesperrt = (a) => offenePflicht(a).length > 0;
const formular = (felder, inhalt, bestaetigen = '') => `<form method="post" action="/webhook/aufgabe" class="entscheiden"${bestaetigen ? ` data-bestaetigen="${esc(bestaetigen)}"` : ''}>
  ${Object.entries(felder).map(([name, wert]) => `<input type="hidden" name="${name}" value="${esc(wert)}">`).join('')}<input type="hidden" name="akteur" value="">${inhalt}</form>`;
const aktionsleiste = (a) => {
  if (anonym || a.status !== 'offen') return '';
  const sperre = PREISARTEN.includes(a.art) && gesperrt(a);
  const knoepfe = ENTSCHEIDBAR.includes(a.art)
    ? (sperre ? `<button class="knopf klein" type="button" disabled title="Erst nach Freigabe durch Technik und QM">${ICON.schloss}Freigeben</button>`
      : formular({ id: a.id, aktion: 'freigegeben' }, `<button class="knopf klein gruen" type="submit">${ICON.haken}Freigeben</button>`))
      + formular({ id: a.id, aktion: 'abgelehnt' }, '<button class="knopf klein rot" type="submit">Ablehnen</button>')
    : formular({ id: a.id, aktion: 'erledigt' }, `<button class="knopf klein gruen" type="submit">${ICON.haken}${a.art === 'entwurf_senden' ? 'Als gesendet markieren' : 'Erledigt'}</button>`);
  // Weiterleiten an einzelne Abteilungen, solange sie im Vorgang noch keine Aufgabe haben
  const ab = a.abteilungen ?? {};
  const fachlich = !['technik_freigabe', 'qm_freigabe', 'bestand_pruefen', 'entwurf_senden'].includes(a.art);
  const ZIELART = { technik: 'technik_freigabe', qm: 'qm_freigabe', dispo: 'bestand_pruefen' };
  const weiter = fachlich ? Object.entries(ZIELART).filter(([, art]) => !(a.ticket_aufgaben ?? []).some((y) => y.art === art))
    .map(([ziel]) => formular({ id: a.id, aktion: 'weiterleiten', ziel }, `<button class="knopf klein leise-knopf${ab[ziel] ? ' empfohlen' : ''}" type="submit">${ICON.pfeil}${NAMEN[ziel]}</button>`)).join('') : '';
  const unterlagen = fachlich && (ab.technik || ab.qm || ab.dispo) && !(a.entwurf_zwecke ?? []).includes('unterlagen_anfordern')
    ? formular({ id: a.id, aktion: 'unterlagen' }, '<button class="knopf klein" type="submit">Erstmuster/Zeugnis anfordern</button>') : '';
  const vorlage = a.team === 'Einkauf' && a.bestellnummer && a.art !== 'entwurf_senden' ? '<a class="knopf klein" href="/form/entwurf">Vorlage</a>' : '';
  return `<footer class="aktionsleiste"><div class="entscheidung">${knoepfe}</div>${weiter || unterlagen || vorlage ? `<div class="weiter"><span class="leise">Weiterleiten</span>${weiter}${unterlagen}${vorlage}</div>` : ''}</footer>`;
};

// Sortierwerte für die Filterleiste. Im Screenshot-Modus nur der Rang, damit der Betrag nicht im Quelltext steht.
const jahresWerte = [...new Set(aufgaben.map((a) => Number(a.details?.jahres_mehrkosten_eur ?? 0)))].sort((x, y) => x - y);
const sortJahr = (a) => { const w = Number(a.details?.jahres_mehrkosten_eur ?? 0); return anonym ? jahresWerte.indexOf(w) : w; };
const sortPrio = (a) => (a.art === 'eskalation' ? 3 : a.prioritaet === 'hoch' ? 2 : a.status === 'offen' ? 1 : 0);

// Historie je Lieferant (über die Absender-Domain) und Vereinbarungen für den Artikel
const domainVon = (s) => (String(s ?? '').match(/@([^>\s]+)/)?.[1] ?? '').toLowerCase();
const HISTORIE = new Map(historie.map((h) => [h.mail_domain, h]));
const hist = (a) => HISTORIE.get(domainVon(a.absender));
const vereinbarungen = (a) => (hist(a)?.vereinbarungen ?? [])
  .filter((v) => !v.artikelnr || v.artikelnr === a.artikelnr || String(a.artikel ?? '').includes(v.artikelnr));
const tag = (d) => (d ? String(d).slice(0, 10).split('-').reverse().join('.') : '–');

// System-Empfehlung: regelbasiert aus geprüften Daten, mit Begründung. Der Vorschlag des Sprachmodells steht getrennt
// in den Befunden. Reihenfolge = Vorrang: Fremdabteilungen und Vereinbarungen schlagen Prozentschwellen.
const empfehlung = (a) => {
  const d = a.details ?? {};
  const ab = a.abteilungen ?? {};
  const auf = a.ticket_aufgaben ?? [];
  const tol = Number(e.preis_toleranz_dispo_prozent ?? 5);
  const E = (ton, text, grund, knopf = '') => ({ ton, text, grund, knopf });
  const jahr = d.jahres_mehrkosten_eur != null ? `Jahreswirkung ${anonym ? '***' : esc(eur(d.jahres_mehrkosten_eur))}.` : '';
  if (a.status === 'info') return E('neutral', 'Zur Kenntnis nehmen.', a.art === 'preis_info' ? 'Preisentwicklung im Blick behalten, keine Aktion nötig.' : '');
  if (a.art === 'entwurf_senden') return E('neutral', 'Entwurf prüfen, Platzhalter füllen, aus deinem Postfach senden und als gesendet markieren.', 'Das System sendet nie selbst.');
  if (a.art === 'technik_freigabe') return E('warn', 'Änderung technisch prüfen und freigeben oder ablehnen.', 'Erst nach den Freigaben von Technik und QM kann der Einkauf den Preis freigeben.');
  if (a.art === 'qm_freigabe') return E('warn', 'Erstmuster bzw. Sonderfreigabe prüfen und freigeben oder ablehnen.', 'Bis zur Freigabe liefert der Lieferant im bisherigen Stand.');
  if (a.art === 'bestand_pruefen') return E('warn', 'Reichweite prüfen und bei Bedarf eine letzte Bestellung (Last-Time-Buy) auslösen.', esc(d.aenderung ?? ''));

  // Andere Abteilungen nötig, aber noch nicht eingebunden
  const fehlt = [...offenePflicht(a).filter(([, art]) => !auf.some((y) => y.art === art)).map(([m]) => m),
    ...(ab.dispo && !auf.some((y) => y.art === 'bestand_pruefen') ? ['dispo'] : [])];
  if (fehlt.length && (ab.technik || ab.qm || ab.dispo)) {
    const grund = ab.werkstoff_alt || ab.werkstoff_neu
      ? `Lieferant ändert den Werkstoff von <span class="num">${esc(ab.werkstoff_alt ?? '?')}</span> auf <span class="num">${esc(ab.werkstoff_neu ?? '?')}</span>.`
      : (ab.regel ?? []).includes('sonderfreigabe') ? 'Lieferant bittet um Sonderfreigabe für eine Abweichung von Maß oder Spezifikation.'
        : (ab.regel ?? []).includes('abkuendigung') ? 'Lieferant kündigt den Artikel ab oder kann ihn nicht mehr liefern.' : 'Das Modell erkennt eine Änderung am Produkt.';
    return E('krit', `${fehlt.map((x) => NAMEN[x]).join(', ')} einbinden.`,
      `${grund}${PREISARTEN.includes(a.art) ? ' Bis zur Freigabe ist die Preisfreigabe gesperrt.' : ''}`,
      anonym ? '' : formular({ id: a.id, aktion: 'einbinden' }, '<button class="knopf klein dunkel" type="submit">Empfehlung ausführen</button>'));
  }
  if (PREISARTEN.includes(a.art)) {
    const fest = vereinbarungen(a).find((v) => v.art === 'festpreis');
    if (fest) return E('krit', 'Ablehnen: Festpreis vereinbart.', `${esc(fest.text)}, gültig bis <span class="num">${tag(fest.gueltig_bis)}</span>.`);
    const warten = offenePflicht(a);
    if (warten.length) return E('warn', `Auf Freigabe von ${warten.map(([m]) => NAMEN[m]).join(' und ')} warten.`, 'Die Preisfreigabe ist bis dahin gesperrt.');
    const gleit = vereinbarungen(a).find((v) => v.art === 'preisgleitklausel');
    if (gleit) return E('warn', 'Index-Nachweis anfordern, bevor du entscheidest.', `${esc(gleit.text)}. ${jahr}`);
    if ((d.eskalation ?? []).includes('liefertreue_und_preis')) {
      return E('krit', 'Alternativlieferant prüfen, Erhöhung nur gegen Kalkulation.', `Liefertreue ${esc(pz(d.liefertreue))} bei ${esc(pz(d.prozent))} Erhöhung. ${jahr}`);
    }
    if (d.prozent_12_monate != null && d.prozent_12_monate > tol) {
      return E('warn', 'Nicht ohne Verhandlung freigeben: Kalkulation anfordern.', `Zusammen ${esc(pz(d.prozent_12_monate))} in zwölf Monaten, mehrere kleine Erhöhungen hintereinander. ${jahr}`);
    }
    if (d.angabe_lieferant_prozent != null) return E('warn', 'Rückfrage beim Lieferanten.', `Er nennt ${esc(pz(d.angabe_lieferant_prozent))}, gerechnet sind es ${esc(pz(d.prozent))}.`);
    const alt = (d.alter_preis_gilt ?? []).length ? ` Bestätigte Bestellungen ${d.alter_preis_gilt.map(nummer).join(', ')} zum alten Preis abrechnen lassen.` : '';
    if (a.art === 'preis_freigeben') return E('ok', 'Freigeben.', `Innerhalb der Kompetenz der Disposition (${esc(pz(d.prozent))}), keine Warnhinweise.${alt}`);
    if (a.art === 'eskalation') return E('warn', 'Entscheiden: über der Freigabegrenze des Einkäufers.', `${jahr}${alt}`);
    return E('warn', 'Verhandeln oder Kalkulation anfordern.', `${jahr || 'Erhöhung über der Freigabegrenze der Disposition.'}${alt}`);
  }
  if (a.art === 'liefertermin_pruefen') return E('warn', 'Beim Lieferanten nachfassen: verbindlichen Termin oder Teillieferung anfordern.', 'Der bestätigte Termin ist später, unsicher oder fehlt.');
  if (a.art === 'ab_klaeren') {
    const g = d.pruefgruende ?? [];
    const m = (d.abweichungen ?? []).find((x) => x.art === 'menge');
    if (g.includes('absender_domain_abweichend')) return E('krit', 'Absender prüfen, nicht an diese Adresse antworten.', 'Die Domain gehört nicht zum Lieferanten, möglicher Betrugsversuch.');
    if ((d.abweichungen ?? []).some((x) => x.art === 'stammdaten_pruefen') || m?.passt_zur_vpe === false) return E('warn', 'Stammdaten korrigieren und Menge bestätigen.', 'Die Verpackungseinheit in den Stammdaten passt nicht zur AB.');
    if (m?.passt_zur_vpe === true) return E('ok', 'Mehrmenge annehmen, wenn der Bedarf es hergibt.', `Aufrundung auf volle Verpackungseinheiten, Mehrwert ${betrag(Math.abs(m.mehrwert ?? 0), m.waehrung)}.`);
    if (g.includes('neuer_lieferant')) return E('warn', 'Kontakt aufnehmen und Termin absichern.', 'Neuer Lieferant ohne Liefertreue-Historie.');
    if (g.includes('blindbestaetigung_verdacht')) return E('warn', 'Bestätigung beim Lieferanten hinterfragen.', 'Die AB kam wenige Minuten nach der Bestellung, möglicherweise ungeprüft.');
    if (g.includes('liefertreue_unter_schwelle')) return E('warn', 'Termin beim Lieferanten absichern.', `Liefertreue ${esc(a.ab_pruefung?.liefertreue)} % unter der Schwelle von ${esc(a.ab_pruefung?.schwelle)} %.`);
    return E('neutral', 'AB prüfen und mit dem Lieferanten klären.', '');
  }
  return E('neutral', 'Mail lesen und bearbeiten oder an die zuständige Stelle weiterleiten.', '');
};
const empfehlungsBox = (a) => {
  const x = empfehlung(a);
  return `<div class="empfehlung ${x.ton}"><div class="empf-kopf">${ICON[{ krit: 'warnung', warn: 'kreis', ok: 'haken', neutral: 'info' }[x.ton]]}<span>System-Empfehlung</span></div>
    <div class="empf-text">${x.text}</div>${x.grund ? `<div class="empf-grund">${x.grund}</div>` : ''}${x.knopf ? `<div class="empf-aktion">${x.knopf}</div>` : ''}<div class="empf-fuss">Regelbasiert aus ${befunde(a).length} geprüften Befunden. Das Sprachmodell liefert nur einen ungeprüften Hinweis.</div></div>`;
};

// Reiter "Historie": Vereinbarungen, letzte Preiserhöhungen, frühere Vorgänge und der Verlauf dieses Vorgangs
const AKTION_TEXT = { freigegeben: 'freigegeben', abgelehnt: 'abgelehnt', erledigt: 'erledigt' };
const verlauf = (a) => {
  const ereignisse = [{ zeit: a.ticket_erstellt, text: 'Mail eingegangen, Vorgang angelegt' }];
  for (const y of a.ticket_aufgaben ?? []) {
    ereignisse.push({ zeit: y.erstellt, text: `${esc(ARTEN[y.art] ?? y.art)} für ${esc(y.team)}` });
    if (y.erledigt) ereignisse.push({ zeit: y.erledigt, text: `${esc(ARTEN[y.art] ?? y.art)}: ${AKTION_TEXT[y.entscheidung] ?? 'erledigt'} von ${person(y.erledigt_von)}` });
  }
  for (const w of a.ticket_entwuerfe ?? []) ereignisse.push({ zeit: w.zeit, text: `Entwurf ${w.art === 'intern' ? 'intern' : 'an Lieferant'}: ${anonym ? AUSGEBLENDET : esc(w.betreff)}` });
  return ereignisse.filter((x) => x.zeit).sort((x, y) => String(x.zeit).localeCompare(String(y.zeit)))
    .map((x) => `<li><span class="num leise">${esc(String(x.zeit).slice(0, 16).replace('T', ' '))}</span><span>${x.text}</span></li>`).join('');
};
const historieHtml = (a) => {
  const h = hist(a);
  const v = vereinbarungen(a);
  const preise = (h?.preise ?? []).slice(0, 4);
  const gesehen = new Set();
  const vorgaenge = (h?.tickets ?? []).filter((t) => t.id !== a.ticket_id && !gesehen.has(t.betreff) && gesehen.add(t.betreff)).slice(0, 4);
  return `<div class="historie">
    <h4>Vereinbarungen</h4>${v.length ? `<ul>${v.map((x) => `<li><span class="badge neutral">${esc(x.art)}</span> ${esc(x.text)}${x.gueltig_bis ? ` <span class="leise">bis <span class="num">${tag(x.gueltig_bis)}</span></span>` : ''}</li>`).join('')}</ul>` : '<p class="leise">Keine aktiven Vereinbarungen.</p>'}
    <h4>Letzte Preisänderungen</h4>${preise.length ? `<ul>${preise.map((x) => `<li><span class="num">${tag(x.gueltig_ab)}</span> ${esc(x.artikelnr)}: ${prozent(x.prozent)} <span class="leise">${anonym ? '' : esc(x.anlass ?? '')}</span></li>`).join('')}</ul>` : '<p class="leise">Keine Preisänderungen erfasst.</p>'}
    <h4>Frühere Vorgänge</h4>${vorgaenge.length ? `<ul>${vorgaenge.map((t) => `<li><span class="num">${esc(t.datum)}</span> ${esc(t.kategorie)}: ${anonym ? AUSGEBLENDET : esc(t.betreff)}</li>`).join('')}</ul>` : '<p class="leise">Keine früheren Vorgänge.</p>'}
    <h4>Verlauf dieses Vorgangs</h4><ol class="zeitleiste">${verlauf(a)}</ol>
  </div>`;
};

const karte = (a) => {
  const liste = befunde(a);
  const ohneDaten = (!a.details || !Object.keys(a.details).length) && a.art !== 'entwurf_senden';
  return `
  <article class="karte${a.art === 'eskalation' ? ' kritisch' : ''}" data-id="${esc(a.id)}" data-jahr="${sortJahr(a)}" data-prio="${sortPrio(a)}">
    <header>
      <div class="kopfzeile"><h3 title="${anonym ? '' : esc(a.lieferant ?? '')}">${lieferant(a.lieferant)}</h3><span class="id num">#${esc(a.ticket_id)}</span>${a.kategorie ? `<span class="kat">${esc(KATEGORIE[a.kategorie] ?? a.kategorie)}</span>` : ''}</div>
      <div class="titel">${status(a)}<span class="art">${esc(ARTEN[a.art] ?? a.art)}</span><span class="meta num">${esc(a.erstellt)}</span></div>
    </header>
    ${empfehlungsBox(a)}
    <div class="reiterleiste" role="tablist">
      <button type="button" class="kreiter" data-tab="fakten" aria-selected="true">Zusammenfassung</button>
      <button type="button" class="kreiter" data-tab="mail" aria-selected="false">Original-Mail</button>
      <button type="button" class="kreiter" data-tab="historie" aria-selected="false">Historie</button>
    </div>
    <div class="tafel" data-panel="fakten">
    ${gitter(a)}
    ${liste.length ? `<ul class="befunde">${liste.join('')}</ul>` : ''}
    ${ohneDaten && (a.zusammenfassung || a.betreff) ? `<p class="text">${anonym ? AUSGEBLENDET : esc(a.zusammenfassung ?? a.betreff)}</p>` : ''}
    ${a.art === 'entwurf_senden' && a.ew_text ? (anonym ? `<p class="text">${AUSGEBLENDET}</p>` : `<div class="entwurf">
      <div class="leise">An: <span class="num">${esc(a.ew_empfaenger)}</span>${a.ew_cc ? ` · Cc: <span class="num">${esc(a.ew_cc)}</span>` : ''}</div>
      ${(a.ew_warnungen ?? []).length ? `<p class="hinweis">${ICON.warnung} Bitte prüfen: ${a.ew_warnungen.map(esc).join(', ')}</p>` : ''}
      <pre><b>${esc(a.ew_betreff)}</b>\n\n${esc(a.ew_text)}</pre></div>`) : ''}
    ${!anonym && a.art !== 'entwurf_senden' && a.entwurf_text && a.team === 'Einkauf' && a.status === 'offen' ? `<details><summary>Antwortentwurf <span class="leise">${esc(a.foermlichkeit)}, ${esc(a.nachdruck)}</span></summary>
      ${(a.entwurf_warnungen ?? []).length ? `<p class="hinweis">${ICON.warnung} Bitte prüfen: ${a.entwurf_warnungen.map(esc).join(', ')}</p>` : ''}
      <pre><b>${esc(a.entwurf_betreff)}</b>\n\n${esc(a.entwurf_text)}</pre></details>` : ''}
    </div>
    <div class="tafel" data-panel="mail" hidden>${anonym ? `<p class="text">${AUSGEBLENDET}</p>` : a.mailtext ? `<pre class="original">${esc(a.mailtext)}</pre>` : '<p class="leise">Kein Mailtext gespeichert (Vorgang aus der Zeit vor dieser Funktion).</p>'}</div>
    <div class="tafel" data-panel="historie" hidden>${historieHtml(a)}</div>
    ${aktionsleiste(a)}
  </article>`;
};

// Kennzahlen oben: offene Eskalationen, offene Reviews, Automatisierungsquote, Jahreswirkung offener Preiserhöhungen
const offen = aufgaben.filter((a) => a.status === 'offen');
const infos = aufgaben.filter((a) => a.status === 'info');
const eskalationen = offen.filter((a) => a.art === 'eskalation').length;
const quote = Number(k.gesamt_30) ? Math.round((Number(k.automatisch_30) / Number(k.gesamt_30)) * 100) : null;
// Jahreswirkung je Ticket nur einmal zählen (Einkäufer und Eskalation tragen dieselben Details)
const jahresJeTicket = new Map();
for (const a of offen) if (a.details?.jahres_mehrkosten_eur != null) jahresJeTicket.set(a.ticket_id, Number(a.details.jahres_mehrkosten_eur));
const jahresSumme = [...jahresJeTicket.values()].reduce((s, x) => s + x, 0);
// Cost Avoidance: Jahreswirkung abgelehnter Preiserhöhungen in diesem Jahr. Vorläufig, weil erst die Antwort des
// Lieferanten zeigt, ob die Erhöhung wirklich ausbleibt. Freigaben zählen nicht: Sie akzeptieren Mehrkosten.
const ziel = Number(e.cost_avoidance_ziel_euro ?? 100000);
const vermieden = Number(k.cost_avoidance_ytd ?? 0);
const anteilGenau = (vermieden / ziel) * 100;
const anteil = Math.min(100, anteilGenau);
// Prognose fürs Jahr: bisheriger Wert linear hochgerechnet (grob, sagt nichts über künftige Erhöhungen)
const heute = new Date();
const tagImJahr = Math.max(1, Math.ceil((heute - new Date(heute.getFullYear(), 0, 1)) / 86400000));
const prognose = Math.round((vermieden / tagImJahr) * 365);
const euroGanz = (n) => `${Math.round(n).toLocaleString('de-DE')}\u00a0€`;
const fortschritt = `<div class="hero" tabindex="0" aria-label="Savings YTD" data-tip="${esc(`Cost Avoidance: Jahreswirkung abgelehnter Preiserhöhungen seit 1. Januar. Vorläufig, bis der Lieferant die Ablehnung akzeptiert. Prognose fürs Jahr bei gleichem Tempo: ${anonym ? '***' : euroGanz(prognose)}.`)}">
  <div class="hero-kopf">${ICON.ziel}<span class="hero-titel">Savings YTD</span><span class="leise">Cost Avoidance, vorläufig</span></div>
  <div class="hero-zahlen"><span class="hero-wert num">${anonym ? '***' : esc(euroGanz(vermieden))}</span><span class="hero-ziel num">von ${anonym ? '***' : esc(euroGanz(ziel))}</span><span class="hero-anteil num">${anteilGenau.toLocaleString('de-DE', { maximumFractionDigits: 1 })}&nbsp;% YTD</span></div>
  <div class="hero-balken"><div style="width:${anteil.toFixed(2)}%"></div></div></div>`;
// Streak: Tage in Folge ohne Rückstau (keine offene Aufgabe älter als die eingestellte Zahl Tage). Belohnt zügiges
// Bearbeiten, nicht schnelles Wegklicken.
const streak = `<span class="streak num" title="Tage in Folge, an denen keine Aufgabe länger als ${esc(e.rueckstau_tage ?? 2)} Tage offen lag">${ICON.blitz}STREAK: ${esc(k.streak_tage ?? 0)} TAGE OHNE RÜCKSTAU</span>`;
// Rang je Bearbeiter nach seinen vermiedenen Mehrkosten (Cost Avoidance), nicht nach der Zahl erledigter Tickets:
// Sonst würde schnelles Durchklicken belohnt. Der Name kommt aus dem Feld "Bearbeiter", das Skript wählt den Rang.
const RAENGE = [[0, 'Buyer'], [5000, 'Senior Buyer'], [25000, 'Negotiator'], [50000, 'Senior Negotiator'], [100000, 'Lead Negotiator']];
const rang = anonym ? '' : `<span class="rang" id="rang" title="Procurement Rank nach vermiedenen Mehrkosten dieses Jahres (Jahreswirkung abgelehnter Preiserhöhungen, vorläufig)">${ICON.stern}<span>Procurement Rank: <b id="rang-name">Bearbeiter eintragen</b></span></span>
  <script type="application/json" id="rang-daten">${JSON.stringify({ raenge: RAENGE, je_person: k.cost_avoidance_je_person ?? {} }).replace(/</g, '\\u003c')}</script>`;

// Übergabe für Vertretung und Einarbeitung: worauf gewartet wird und was als Nächstes zu tun ist
const wartend = (aufgaben ?? []).filter((a) => a.status === 'offen' && ['technik_freigabe', 'qm_freigabe', 'bestand_pruefen'].includes(a.art));
const entwuerfeOffen = (aufgaben ?? []).filter((a) => a.status === 'offen' && a.art === 'entwurf_senden').length;
const uebergabe = `<section class="uebergabe" data-vertretung hidden>
  <h2>Übergabe</h2>
  <div class="ueb-raster">
    <div><div class="kpi-titel">Wartet auf andere Abteilungen</div>${wartend.length ? `<ul>${wartend.map((a) => `<li>${lieferant(a.lieferant)} · ${esc(ARTEN[a.art])} <span class="leise">seit <span class="num">${esc(a.erstellt)}</span></span></li>`).join('')}</ul>` : '<p class="leise">Nichts.</p>'}</div>
    <div><div class="kpi-titel">Als Nächstes</div><ul>
      <li><span class="num">${(aufgaben ?? []).filter((a) => a.status === 'offen' && a.art === 'eskalation').length}</span> Eskalationen entscheiden</li>
      <li><span class="num">${entwuerfeOffen}</span> Entwürfe prüfen und senden</li>
      <li><span class="num">${reviews.length}</span> Mails in der Review-Queue zuordnen</li>
    </ul><p class="leise">In jeder Karte zeigt der Reiter „Historie“ Vereinbarungen, letzte Preisänderungen und den Verlauf des Vorgangs.</p></div>
  </div></section>`;
const meldung = String($('Webhook Arbeitsliste').first().json.query?.meldung ?? '').slice(0, 200);

const kpi = (titel, wert, unter, ton = '') => `<div class="kpi ${ton}"><div class="kpi-titel">${titel}</div><div class="kpi-wert num">${wert}</div><div class="kpi-unter">${unter}</div></div>`;
const kennzahlen = `<section class="kpis">
  ${kpi('Offene Eskalationen', eskalationen, 'Einkaufsleitung und Geschäftsleitung', eskalationen ? 'krit' : '')}
  ${kpi('Offene Reviews', reviews.length, 'Entscheidung durch einen Menschen', reviews.length ? 'warn' : '')}
  ${kpi('Auto-Quote 30 Tage', quote === null ? '–' : `${quote}&nbsp;%`, `<span class="num">${esc(k.automatisch_30)}</span> von <span class="num">${esc(k.gesamt_30)}</span> Mails ohne Review`)}
  ${kpi('Jahreswirkung offen', anonym ? '***.*** €' : `${Math.round(jahresSumme).toLocaleString('de-DE')}&nbsp;€`, `aus <span class="num">${jahresJeTicket.size}</span> offenen Preisänderungen`)}
</section>`;

const REIHENFOLGE = ['Geschäftsleitung', 'Einkaufsleitung', 'Technik', 'Qualitätsmanagement', 'Einkauf', 'Disposition', 'Strategischer Einkauf'];
const teams = [...new Set(offen.map((a) => a.team))]
  .sort((x, y) => ((REIHENFOLGE.indexOf(x) + 1 || 99) - (REIHENFOLGE.indexOf(y) + 1 || 99)) || x.localeCompare(y));
// Master-Detail: links die Queue, rechts die gewählte Aufgabe. Mehrere offene Aufgaben eines Lieferanten bilden eine
// Sammelakte mit gemeinsamer Übersicht und Sammelaktionen. Alle Karten liegen schon auf der Seite, der Browser zeigt nur die gewählte.
const jahrSumme = (liste) => {
  const je = new Map();
  for (const a of liste) if (a.details?.jahres_mehrkosten_eur != null) je.set(a.ticket_id, Number(a.details.jahres_mehrkosten_eur));
  return [...je.values()].reduce((s, x) => s + x, 0);
};
const zeile = (a) => {
  const jahr = a.details?.jahres_mehrkosten_eur;
  return `<button type="button" class="zeile" data-id="${esc(a.id)}" data-team="${esc(a.team)}" data-jahr="${sortJahr(a)}" data-prio="${sortPrio(a)}" aria-selected="false">
    <span class="z-oben">${status(a)}<span class="meta num">${esc(String(a.erstellt ?? '').slice(-5))}</span></span>
    <span class="z-art">${esc(ARTEN[a.art] ?? a.art)}</span>
    <span class="z-unten"><span class="leise">${esc(a.team)}</span>${jahr != null ? `<span class="z-jahr">${betrag(jahr)}<span class="leise"> / Jahr</span></span>` : ''}</span>
  </button>`;
};
const lieferantenGruppen = new Map();
for (const a of offen) {
  const schluessel = String(a.lieferant ?? domainVon(a.absender) ?? a.id);
  if (!lieferantenGruppen.has(schluessel)) lieferantenGruppen.set(schluessel, []);
  lieferantenGruppen.get(schluessel).push(a);
}
const gruppenListe = [...lieferantenGruppen.values()];
const queueHtml = gruppenListe.map((liste, nr) => {
  const mehr = liste.length > 1;
  const jahr = jahrSumme(liste);
  const kopf = `<span class="g-name">${lieferant(liste[0].lieferant)}</span>${mehr ? `<span class="badge neutral">Sammelakte · ${liste.length}</span>` : ''}${jahr ? `<span class="z-jahr">${betrag(jahr)}</span>` : ''}`;
  return `<div class="gruppe" data-jahr="${Math.max(...liste.map(sortJahr))}" data-prio="${Math.max(...liste.map(sortPrio))}" data-id="${Math.max(...liste.map((a) => Number(a.id)))}">
    ${mehr ? `<button type="button" class="g-kopf" data-akte="${nr}" aria-selected="false">${kopf}</button>` : `<div class="g-kopf einzel">${kopf}</div>`}
    ${liste.map(zeile).join('')}</div>`;
}).join('');

// Sammelakte: gemeinsame Übersicht. Sammelaktionen gibt es nur für Preisaufgaben unterhalb der Eskalation. "Freigeben" betrifft
// ausschließlich Aufgaben, für die die System-Empfehlung "Freigeben" lautet. Der Server prüft jede Aufgabe einzeln erneut.
const akteHtml = gruppenListe.map((liste, nr) => {
  if (liste.length < 2) return '';
  const preis = liste.filter((a) => PREISARTEN.includes(a.art) && a.art !== 'eskalation');
  const frei = preis.filter((a) => !gesperrt(a) && empfehlung(a).ton === 'ok');
  const jahr = jahrSumme(liste);
  const sammel = anonym ? '' : `<div class="bulk"><span class="leise">Sammelaktion: Jede Aufgabe wird einzeln geprüft und mit deinem Namen protokolliert.</span><div class="bulk-knoepfe">
      ${frei.length ? `<button type="button" class="knopf gruen" data-bulk="freigegeben" data-ids="${frei.map((a) => a.id).join(',')}">${ICON.haken}Empfohlene freigeben<span class="num">${frei.length}</span></button>` : ''}
      ${preis.length ? `<button type="button" class="knopf rot" data-bulk="abgelehnt" data-ids="${preis.map((a) => a.id).join(',')}">Preisaufgaben ablehnen<span class="num">${preis.length}</span></button>` : ''}
      ${!frei.length && !preis.length ? '<span class="leise">Keine Sammelaktion möglich, bitte die Aufgaben einzeln entscheiden.</span>' : ''}</div></div>`;
  return `<section class="akte" data-akte="${nr}" hidden>
    <header><h3>${lieferant(liste[0].lieferant)}</h3><span class="badge neutral">Sammelakte</span></header>
    <p class="text">${liste.length} offene Aufgaben${jahr ? `, Jahreswirkung zusammen ${betrag(jahr)}` : ''}. Wähle eine Aufgabe für die Details oder entscheide gebündelt.</p>
    <ul class="akte-liste">${liste.map((a) => { const x = empfehlung(a); return `<li><button type="button" class="akte-zeile" data-open="${esc(a.id)}">${status(a)}<span class="z-art">${esc(ARTEN[a.art] ?? a.art)}</span><span class="leise">${esc(a.team)}</span></button><div class="akte-empf ${x.ton}">${x.text}</div></li>`; }).join('')}</ul>
    ${sammel}</section>`;
}).join('');

const arbeitsraum = offen.length ? `<div class="arbeitsraum">
  <nav class="queue" aria-label="Offene Aufgaben">${queueHtml}</nav>
  <section class="detail" aria-live="polite">${akteHtml}${offen.map(karte).join('')}<p class="leer detail-leer" hidden>Alles erledigt. Keine offenen Aufgaben.</p></section>
</div>` : '<p class="leer">Keine offenen Aufgaben.</p>';

// Daten für "Ask ProcurePulse": regelbasierte Antworten aus den Daten dieser Seite, keine Cloud, kein Modellaufruf
const nurText = (s) => String(s ?? '').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const kontextDaten = anonym ? {} : Object.fromEntries(offen.map((a) => {
  const d = a.details ?? {};
  const x = empfehlung(a);
  return [a.id, {
    lieferant: a.lieferant ?? '', art: ARTEN[a.art] ?? a.art, prozent: d.prozent ?? null, p12: d.prozent_12_monate ?? null,
    jahr: d.jahres_mehrkosten_eur ?? null, liefertreue: d.liefertreue ?? null,
    preise: (hist(a)?.preise ?? []).slice(0, 6).map((p) => ({ d: tag(p.gueltig_ab), a: p.artikelnr, p: p.prozent })),
    vereinbarungen: vereinbarungen(a).map((v) => `${v.art}: ${v.text}`),
    empfehlung: nurText(`${x.text} ${x.grund}`),
  }];
}));
const kontextJson = JSON.stringify(kontextDaten).replace(/</g, '\\u003c');
const copilotHtml = anonym ? '' : `<aside id="copilot" class="copilot" hidden aria-label="Ask ProcurePulse">
  <header><span class="cp-titel">${ICON.funke}Ask ProcurePulse</span><button type="button" class="knopf klein" id="copilot-zu" aria-label="Schließen">Schließen</button></header>
