};
const REGEL = {
  bankdatenaenderung: 'Regel: Mails mit geänderter Bankverbindung gehen immer an einen Menschen, unabhängig von der Konfidenz',
  prompt_injection_verdacht: 'Regel: Text enthält typische Anweisungen an das Modell',
  kategorie_unplausibel: 'Regel: Angebot oder Preiserhöhung mit unserer Bestellnummer (45 + 8 Ziffern) ist vermutlich eine AB',
