</style></head><body>
<div class="kopf"><div class="kopf-innen">
  <div class="marke">${ICON.puls}ProcurePulse<span>Local-First Procurement Operations</span></div>
  <nav class="aktionen">
    ${anonym ? '' : '<label class="bearbeiter">Bearbeiter<input id="bearbeiter" autocomplete="name" placeholder="Vor- und Nachname"></label>'}
    ${sammelknopf}
    <a class="knopf" href="/form/review">Review abschließen</a>
    <a class="knopf" href="/form/entwurf">Antwortentwurf</a>
    <button type="button" class="knopf" id="vertretung" aria-pressed="false">Vertretungsmodus</button>
    ${anonym ? '' : `<button type="button" class="knopf" id="copilot-an">${ICON.funke}Ask ProcurePulse</button>`}
    <a class="knopf${anonym ? ' aktiv' : ' primaer'}" href="${anonym ? '?' : '?anonym=1'}">${anonym ? ICON.offen + 'Screenshot-Modus beenden' : ICON.schloss + 'Screenshot-Modus (Anonymisieren)'}</a>
  </nav>
</div>
<div class="kopf-unten">${fortschritt}<div class="chips"><span class="lokal" title="Sprachmodell, Datenbank und Workflows laufen lokal im Docker-Netz. Keine Cloud-KI."><span class="puls"></span>Lokal · keine Cloud</span>${streak}${rang}</div></div>
</div>
<main>
${anonym ? `<div class="banner">${ICON.schloss}<div><b>Screenshot-Modus aktiv.</b> Lieferanten, Bestellnummern, Personen und Beträge sind auf dem Server ersetzt, Mailtexte, Betreffs und Entwürfe ausgeblendet. Prozentwerte, Daten und Regeln bleiben sichtbar.</div></div>` : ''}
${kennzahlen}
${uebergabe}
${filterleiste}
${arbeitsraum}
<section class="bereich" data-team="__rest"><h2>Review-Queue<span class="zaehler num">${reviews.length}</span></h2>
  ${reviewZeilen ? `<div class="tabelle"><table><tr><th>ID</th><th>Gründe</th><th>Mail</th><th>Vorschlag LLM</th><th>Eingang</th></tr>${reviewZeilen}</table></div>` : '<p class="leer">Keine offenen Reviews.</p>'}
</section>
<section class="bereich" data-team="__rest"><h2>Infos der letzten 30 Tage<span class="zaehler num">${infos.length}</span></h2>
  ${infos.length ? `<div class="raster">${infos.map(karte).join('')}</div>` : '<p class="leer">Keine Infos.</p>'}
</section>
<section class="bereich" data-team="__rest"><h2>Audit-Protokoll ${kette}</h2>
  ${auditZeilen ? `<div class="tabelle"><table><tr><th>Zeit</th><th>Wer</th><th>Entscheidung</th><th>Notiz</th><th>Hash</th></tr>${auditZeilen}</table></div>` : '<p class="leer">Noch keine Entscheidungen protokolliert.</p>'}
</section>
</main>
${meldung && !anonym ? `<div class="toast" role="status">${ICON.haken}<span>${esc(meldung)}</span></div>` : ''}
${copilotHtml}
<script>
(() => {
  // Name des Bearbeiters: einmal eingeben, bleibt im Browser gespeichert und geht mit jeder Entscheidung ins Audit-Protokoll
  const feld = document.getElementById('bearbeiter');
  try { if (feld) feld.value = localStorage.getItem('bearbeiter') || ''; } catch (_) {}
  feld?.addEventListener('change', () => { try { localStorage.setItem('bearbeiter', feld.value.trim()); } catch (_) {} });
  feld?.addEventListener('input', () => feld.classList.remove('fehlt'));
  const rangDaten = JSON.parse(document.getElementById('rang-daten')?.textContent || '{}');
  const setzeRang = () => {
    const ziel = document.getElementById('rang-name');
    if (!ziel || !rangDaten.raenge) return;
    const name = feld ? feld.value.trim() : '';
    if (!name) { ziel.textContent = 'Bearbeiter eintragen'; return; }
    const summe = Number(rangDaten.je_person?.[name] ?? 0);
    ziel.textContent = rangDaten.raenge.filter(([ab]) => summe >= ab).pop()[1];
    // Keine Backticks: Dieses Skript steht selbst in einem Template-String des Code-Nodes
    document.getElementById('rang')?.setAttribute('title', 'Procurement Rank nach vermiedenen Mehrkosten dieses Jahres: ' + Math.round(summe).toLocaleString('de-DE') + ' € (vorläufig)');
  };
  feld?.addEventListener('input', setzeRang);
  setzeRang();
  // Entscheiden: Freigeben, Ablehnen und Erledigt sind optimistisch. Die Karte verschwindet sofort, der Server wird im Hintergrund
  // gefragt. Lehnt er ab, lädt die Seite neu und zeigt den echten Stand. Alle anderen Aktionen laden die Seite neu.
  const NL = String.fromCharCode(10);
  const weniger = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const zeilen = () => [...document.querySelectorAll('.queue .zeile')];
  const sichtbar = (e) => !e.closest('[hidden]');
  let aktuell = null;
  const zeigeToast = (text) => {
    let t = document.querySelector('.toast');
    if (!t) { t = document.createElement('div'); t.className = 'toast'; t.setAttribute('role', 'status'); document.body.appendChild(t); }
    t.classList.remove('aus'); t.textContent = text;
    clearTimeout(zeigeToast.uhr); zeigeToast.uhr = setTimeout(() => t.classList.add('aus'), 5000);
  };
  const kontextCopilot = () => {
    const ziel = document.getElementById('cp-kontext');
    const c = aktuell && copilotDaten[aktuell];
    if (ziel) ziel.textContent = c ? c.lieferant + ' · ' + c.art : 'Wähle links einen Vorgang.';
  };
  const waehleKarte = (id) => {
    aktuell = String(id);
    document.querySelectorAll('.detail .akte').forEach((a) => { a.hidden = true; });
    document.querySelectorAll('.detail .karte').forEach((k) => { k.hidden = k.dataset.id !== aktuell; });
    zeilen().forEach((z) => z.setAttribute('aria-selected', String(z.dataset.id === aktuell)));
    document.querySelectorAll('button.g-kopf').forEach((g) => g.setAttribute('aria-selected', 'false'));
    kontextCopilot();
    if (window.innerWidth < 900) document.querySelector('.detail')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };
  const waehleAkte = (nr) => {
    aktuell = null;
    document.querySelectorAll('.detail .karte').forEach((k) => { k.hidden = true; });
    document.querySelectorAll('.detail .akte').forEach((a) => { a.hidden = a.dataset.akte !== String(nr); });
    zeilen().forEach((z) => z.setAttribute('aria-selected', 'false'));
    document.querySelectorAll('button.g-kopf').forEach((g) => g.setAttribute('aria-selected', String(g.dataset.akte === String(nr))));
    kontextCopilot();
  };
  const waehleErste = () => {
    const z = zeilen().find(sichtbar);
    if (z) waehleKarte(z.dataset.id);
    else {
      aktuell = null;
      document.querySelectorAll('.detail .karte, .detail .akte').forEach((k) => { k.hidden = true; });
      const leer = document.querySelector('.detail-leer'); if (leer) leer.hidden = false;
    }
  };
  const zaehle = () => {
    document.querySelectorAll('[data-filter]').forEach((r) => {
      const n = zeilen().filter((z) => r.dataset.filter === 'alle' || z.dataset.team === r.dataset.filter).length;
      const c = r.querySelector('.num'); if (c) c.textContent = String(n);
    });
  };
  const entferne = (id) => {
    const z = document.querySelector('.queue .zeile[data-id="' + id + '"]');
    const gruppe = z?.closest('.gruppe');
    z?.remove(); document.querySelector('.detail .karte[data-id="' + id + '"]')?.remove();
    document.querySelectorAll('[data-open="' + id + '"]').forEach((x) => x.closest('li')?.remove());
    if (gruppe && !gruppe.querySelector('.zeile')) gruppe.remove();
    zaehle();
  };
  const naechste = (id) => {
    const liste = zeilen().filter(sichtbar); const i = liste.findIndex((z) => z.dataset.id === String(id));
    const n = liste[i + 1] ?? liste[i - 1];
    return n && n.dataset.id !== String(id) ? n.dataset.id : null;
  };
  const gespeichert = (r) => r.ok && new URL(r.url).pathname.endsWith('/webhook/arbeitsliste');
  const sende = (form, karte) => {
    const id = karte.dataset.id; const t0 = performance.now();
    const daten = new URLSearchParams(new FormData(form));
    const folge = naechste(id);
    karte.classList.add('weg');
    setTimeout(() => { entferne(id); if (folge) waehleKarte(folge); else waehleErste(); }, weniger ? 0 : 220);
    fetch(form.action, { method: 'POST', body: daten, credentials: 'same-origin' }).then((r) => {
      if (!gespeichert(r)) throw new Error('nicht gespeichert');
      zeigeToast((new URL(r.url).searchParams.get('meldung') || 'Gespeichert') + ' · ' + Math.round(performance.now() - t0) + ' ms');
    }).catch(() => { zeigeToast('Nicht gespeichert. Die Liste wird neu geladen.'); setTimeout(() => window.location.reload(), 1500); });
  };
  document.addEventListener('submit', (ereignis) => {
    const form = ereignis.target;
    if (!form.matches('form.entscheiden')) return;
    const name = feld ? feld.value.trim() : '';
    if (!name) { ereignis.preventDefault(); feld?.classList.add('fehlt'); feld?.focus(); return; }
    form.querySelector('input[name=akteur]').value = name;
    if (form.dataset.bestaetigen && !window.confirm(form.dataset.bestaetigen)) { ereignis.preventDefault(); return; }
    const karte = form.closest('.karte');
    const aktion = form.querySelector('input[name=aktion]')?.value;
    if (karte && ['freigegeben', 'abgelehnt', 'erledigt'].includes(aktion)) { ereignis.preventDefault(); sende(form, karte); }
  });

  // Sammelaktion einer Sammelakte: jede Aufgabe geht einzeln an den Server, der sie erneut prüft und protokolliert
  const sammelaktion = async (knopf) => {
    const name = feld ? feld.value.trim() : '';
    if (!name) { feld?.classList.add('fehlt'); feld?.focus(); return; }
    const ids = knopf.dataset.ids.split(',');
    const wort = knopf.dataset.bulk === 'freigegeben' ? 'freigeben' : 'ablehnen';
    if (!window.confirm(ids.length + ' Aufgaben ' + wort + '? Jede Entscheidung wird einzeln geprüft und mit deinem Namen protokolliert.')) return;
    knopf.disabled = true; const t0 = performance.now(); let ok = 0;
    for (const id of ids) {
      try {
        const r = await fetch('/webhook/aufgabe', { method: 'POST', body: new URLSearchParams({ id: id, aktion: knopf.dataset.bulk, akteur: name }), credentials: 'same-origin' });
        if (gespeichert(r)) ok++;
      } catch (_) { /* zählt als nicht gespeichert */ }
    }
    const text = ok + ' von ' + ids.length + (knopf.dataset.bulk === 'freigegeben' ? ' freigegeben' : ' abgelehnt') + ' · ' + Math.round(performance.now() - t0) + ' ms';
    window.location.href = '/webhook/arbeitsliste?meldung=' + encodeURIComponent(text);
  };

  document.addEventListener('click', (ereignis) => {
    const ziel = ereignis.target;
    const z = ziel.closest('.zeile'); if (z) { waehleKarte(z.dataset.id); return; }
    const g = ziel.closest('button.g-kopf'); if (g) { waehleAkte(g.dataset.akte); return; }
    const o = ziel.closest('[data-open]'); if (o) { waehleKarte(o.dataset.open); return; }
    const b = ziel.closest('[data-bulk]'); if (b) sammelaktion(b);
  });

  // Tastatur: j und k wechseln den Vorgang, Escape schließt den Copiloten
  document.addEventListener('keydown', (ereignis) => {
    if (ereignis.key === 'Escape' && copilot && !copilot.hidden) { copilot.hidden = true; return; }
    if (ereignis.target.closest('input, select, textarea') || ereignis.metaKey || ereignis.ctrlKey || ereignis.altKey) return;
    if (ereignis.key !== 'j' && ereignis.key !== 'k') return;
    const liste = zeilen().filter(sichtbar); if (!liste.length) return;
    const i = liste.findIndex((z) => z.dataset.id === aktuell);
    const n = liste[Math.max(0, Math.min(liste.length - 1, i + (ereignis.key === 'j' ? 1 : -1)))];
    waehleKarte(n.dataset.id); n.scrollIntoView({ block: 'nearest' });
  });

  // Ask ProcurePulse: regelbasierte Antworten aus den Daten dieser Seite. Texte kommen per textContent in die Seite.
  const copilot = document.getElementById('copilot');
  const copilotDaten = JSON.parse(document.getElementById('copilot-daten')?.textContent || '{}');
  const verlaufBox = document.getElementById('cp-verlauf');
  const sage = (text, wer) => {
    if (!verlaufBox) return;
    const d = document.createElement('div'); d.className = 'cp-nachricht ' + wer; d.textContent = text;
    verlaufBox.appendChild(d); verlaufBox.scrollTop = verlaufBox.scrollHeight;
  };
  const prozentText = (n) => Number(n).toLocaleString('de-DE', { maximumFractionDigits: 1 }) + ' %';
  const ANTWORTEN = {
    historie: (c) => c.preise.length ? 'Letzte Preisänderungen von ' + c.lieferant + ':' + NL + c.preise.map((p) => '• ' + p.d + ' ' + p.a + ': ' + prozentText(p.p)).join(NL) : 'Für ' + c.lieferant + ' sind keine Preisänderungen erfasst.',
    zwoelf: (c) => c.p12 != null ? 'In zwölf Monaten zusammen ' + prozentText(c.p12) + (c.prozent != null ? ', davon die aktuelle Erhöhung ' + prozentText(c.prozent) : '') + '.' : 'Für diesen Vorgang liegt kein Zwölf-Monats-Vergleich vor.',
    vereinbarung: (c) => c.vereinbarungen.length ? 'Aktive Vereinbarungen:' + NL + c.vereinbarungen.map((v) => '• ' + v).join(NL) : 'Mit diesem Lieferanten sind keine aktiven Vereinbarungen erfasst.',
    jahr: (c) => c.jahr != null ? 'Jahreswirkung: ' + Math.round(c.jahr).toLocaleString('de-DE') + ' €' + (c.liefertreue != null ? ', Liefertreue ' + c.liefertreue + ' %.' : '.') : 'Die Jahreswirkung lässt sich nicht berechnen, meist fehlt der Jahresbedarf.',
    warum: (c) => {
      const karte = document.querySelector('.detail .karte[data-id="' + aktuell + '"]');
      const befunde = karte ? [...karte.querySelectorAll('.befund > span:not(.tip)')].map((s) => '• ' + s.textContent.trim()) : [];
      return 'Empfehlung: ' + c.empfehlung + (befunde.length ? NL + 'Geprüfte Befunde:' + NL + befunde.join(NL) : '');
    },
  };
  const frage = (schluessel, anzeige) => {
    sage(anzeige, 'ich');
    const c = aktuell && copilotDaten[aktuell];
    if (!c) { sage('Wähle zuerst links einen einzelnen Vorgang.', 'sys'); return; }
    sage(ANTWORTEN[schluessel](c), 'sys');
  };
  const erkenne = (t) => {
    const s = t.toLowerCase();
    if (/histor|preisverlauf|letzte/.test(s)) return 'historie';
    if (/zwölf|zwoelf|12|monat/.test(s)) return 'zwoelf';
    if (/vereinbar|vertrag|festpreis|gleitklausel/.test(s)) return 'vereinbarung';
    if (/jahr|mehrkosten/.test(s)) return 'jahr';
    if (/warum|empfehl|begründ|grund/.test(s)) return 'warum';
    return null;
  };
  document.querySelectorAll('[data-frage]').forEach((b) => b.addEventListener('click', () => frage(b.dataset.frage, b.textContent.trim())));
  document.getElementById('cp-form')?.addEventListener('submit', (ereignis) => {
    ereignis.preventDefault();
    const eingabe = document.getElementById('cp-eingabe'); const text = eingabe.value.trim(); if (!text) return;
    eingabe.value = '';
    const art = erkenne(text);
    if (art) frage(art, text);
    else { sage(text, 'ich'); sage('Freie Fragen an das lokale Sprachmodell sind noch nicht angebunden. Frag nach Preishistorie, Zwölf-Monats-Vergleich, Vereinbarungen, Jahreswirkung oder der Begründung der Empfehlung.', 'sys'); }
  });
  document.getElementById('copilot-an')?.addEventListener('click', () => { if (copilot) { copilot.hidden = !copilot.hidden; if (!copilot.hidden) document.getElementById('cp-eingabe')?.focus(); } });
  document.getElementById('copilot-zu')?.addEventListener('click', () => { if (copilot) copilot.hidden = true; });

  // Reiter in der Karte: Zusammenfassung, Original-Mail, Historie
  const zeige = (karte, tab) => {
    karte.querySelectorAll('[data-tab]').forEach((b) => b.setAttribute('aria-selected', String(b.dataset.tab === tab)));
    karte.querySelectorAll('[data-panel]').forEach((p) => { p.hidden = p.dataset.panel !== tab; });
  };
  document.addEventListener('click', (ereignis) => {
    const knopf = ereignis.target.closest('[data-tab]');
    if (knopf) zeige(knopf.closest('.karte'), knopf.dataset.tab);
  });

  // Vertretungsmodus: Übergabe oben und in jeder Karte die Historie mit dem Verlauf des Vorgangs
  const schalter = document.getElementById('vertretung');
  const setzeVertretung = (an) => {
    schalter?.setAttribute('aria-pressed', String(an));
    schalter?.classList.toggle('aktiv', an);
    document.querySelectorAll('[data-vertretung]').forEach((x) => { x.hidden = !an; });
    document.querySelectorAll('.karte').forEach((karte) => zeige(karte, an ? 'historie' : 'fakten'));
    try { localStorage.setItem('vertretung', an ? '1' : '0'); } catch (_) {}
  };
  schalter?.addEventListener('click', () => setzeVertretung(schalter.getAttribute('aria-pressed') !== 'true'));
  try { if (localStorage.getItem('vertretung') === '1') setzeVertretung(true); } catch (_) {}

  // Hinweis nach einer Aktion: kurz zeigen, dann ausblenden und die Meldung aus der Adresse entfernen
  const hinweis = document.querySelector('.toast');
  if (hinweis) {
    setTimeout(() => hinweis.classList.add('aus'), 6000);
    const url = new URL(window.location.href); url.searchParams.delete('meldung');
    window.history.replaceState(null, '', url);
  }

  // Filter nach Team: blendet Zeilen und leere Gruppen aus, Review, Infos und Audit gibt es nur bei "Alle"
  const reiter = document.querySelectorAll('[data-filter]');
  let filter = 'alle';
  const filtere = () => {
    zeilen().forEach((z) => { z.hidden = filter !== 'alle' && z.dataset.team !== filter; });
    document.querySelectorAll('.queue .gruppe').forEach((g) => { g.hidden = !g.querySelector('.zeile:not([hidden])'); });
    document.querySelectorAll('section[data-team="__rest"]').forEach((s) => { s.hidden = filter !== 'alle'; });
    const offenAkte = [...document.querySelectorAll('.detail .akte')].some((a) => !a.hidden);
    const gewaehlt = zeilen().some((z) => z.dataset.id === aktuell && sichtbar(z));
    if (!gewaehlt && !offenAkte) waehleErste();
  };
  reiter.forEach((r) => r.addEventListener('click', () => {
    reiter.forEach((x) => x.setAttribute('aria-selected', String(x === r)));
    filter = r.dataset.filter; filtere();
  }));

  // Sortierung: Lieferantengruppen und die Aufgaben darin
  const auswahl = document.getElementById('sortierung');
  const wert = (e, schluessel) => Number(e.dataset[schluessel] || 0);
  const sortiere = () => {
    const queue = document.querySelector('.queue'); if (!queue) return;
    const nach = auswahl.value;
    const vergleiche = (x, y) => nach === 'jahr' ? wert(y, 'jahr') - wert(x, 'jahr')
      : nach === 'prio' ? wert(y, 'prio') - wert(x, 'prio') || wert(y, 'jahr') - wert(x, 'jahr')
      : wert(y, 'id') - wert(x, 'id');
    [...queue.querySelectorAll('.gruppe')].sort(vergleiche).forEach((g) => {
      queue.appendChild(g);
      [...g.querySelectorAll('.zeile')].sort(vergleiche).forEach((z) => g.appendChild(z));
    });
  };
  auswahl?.addEventListener('change', sortiere);
  if (auswahl) sortiere();
  waehleErste();
})();
</script>
</body></html>`;

return { json: { html } };

