parameters.jsCode:
// Entscheidung aus der Arbeitsliste prüfen, bevor etwas in der Datenbank landet
const anfrage = $input.first().json;
const kopf = anfrage.headers ?? {};
const daten = anfrage.body ?? {};
const fehler = [];

// Schutz gegen untergeschobene Formulare (CSRF): Der Browser schickt die Basic-Auth-Daten auch mit, wenn ein Formular
// auf einer fremden Seite hierher sendet. Deshalb muss die Anfrage von der Arbeitsliste auf demselben Host kommen.
const herkunft = String(kopf.origin ?? '');
if (![`http://${kopf.host}`, `https://${kopf.host}`].includes(herkunft)) fehler.push('Die Anfrage kommt nicht von der Arbeitsliste.');

const sammel = daten.sammel === '1';
const id = Number.parseInt(daten.id, 10);
const aktion = sammel ? 'freigegeben' : String(daten.aktion ?? '');
const akteur = String(daten.akteur ?? '').trim().slice(0, 100);
const notiz = String(daten.notiz ?? '').trim().slice(0, 500) || null;
// einbinden: Technik und QM (bei Abkündigung auch Disposition) bekommen Aufgaben, dazu ein interner Entwurf
// unterlagen: Entwurf an den Lieferanten mit Anforderung von Datenblatt, Zeugnis 3.1 und Erstmustern
// weiterleiten: genau eine Abteilung (ziel = technik, qm oder dispo) bekommt eine Aufgabe und einen internen Entwurf
if (!['freigegeben', 'abgelehnt', 'erledigt', 'einbinden', 'unterlagen', 'weiterleiten'].includes(aktion)) fehler.push('Unbekannte Aktion.');
const ziel = String(daten.ziel ?? '');
if (aktion === 'weiterleiten' && !['technik', 'qm', 'dispo'].includes(ziel)) fehler.push('Unbekannte Abteilung.');
if (!sammel && !(id > 0)) fehler.push('Keine Aufgabe angegeben.');
if (!akteur) fehler.push('Der Name des Bearbeiters fehlt.');

// Absolute Rücksprungadresse aus der geprüften Herkunft: Eine relative Adresse macht n8n zu "https:///..."
const zurueck = `${fehler.length ? '' : herkunft}/webhook/arbeitsliste`;
return [{ json: { gueltig: fehler.length === 0, fehler, id: sammel ? null : id, aktion, ziel, akteur, notiz, sammel, zurueck } }];

// Entscheidung in Datenbank-Schritte übersetzen und die passenden Entwürfe aus Vorlagen bauen.
// Bewusst ohne LLM (wie der Antwortentwurf): Vorlagen können nichts erfinden. Gesendet wird nie automatisch,
// jeder Entwurf wird eine Aufgabe "Entwurf prüfen und senden" für den zuständigen Einkäufer.
const p = $('Entscheidung prüfen').first().json;
const zeilen = $input.all().map((i) => i.json).filter((z) => z.id);
const ENTSCHEIDBAR = ['preis_freigeben', 'preiserhoehung_pruefen', 'eskalation', 'technik_freigabe', 'qm_freigabe'];
const PREIS = ['preis_freigeben', 'preiserhoehung_pruefen', 'eskalation'];

if (!zeilen.length) {
  return [{ json: { zulaessig: false, fehler: [p.sammel ? 'Es ist keine unkritische AB mehr offen.' : 'Die Aufgabe ist nicht mehr offen.'] } }];
}

const zahl = (n) => Number(n).toLocaleString('de-DE', { maximumFractionDigits: 4 });
const pz = (n) => `${Number(n).toLocaleString('de-DE', { maximumFractionDigits: 1 })} %`;
const datum = (d) => (d ? String(d).slice(0, 10).split('-').reverse().join('.') : '[Datum]');
const anrede = (z) => {
  const nachname = (z.ansprechpartner ?? '').split(' ').slice(-1)[0];
  if (!nachname) return 'Sehr geehrte Damen und Herren,';
  return `${z.anrede === 'Frau' ? 'Sehr geehrte Frau' : 'Sehr geehrter Herr'} ${nachname},`;
};
const brief = (z, saetze) => [anrede(z), '', ...saetze.flatMap((s) => [s, '']), 'Mit freundlichen Grüßen', z.einkaeufer ?? '[Name]', 'Hagemann Antriebstechnik GmbH'].join('\n');
const platzhalter = (text) => [...new Set(text.match(/\[[^\]]+\]/g) ?? [])].map((x) => `Platzhalter ausfüllen: ${x}`);
const lieferantEntwurf = (z, zweck, betreff, saetze) => {
  const text = brief(z, saetze);
  return { art: 'lieferant', zweck, empfaenger: z.absender, cc: null, betreff, text, warnungen: platzhalter(text) };
};
const bezug = (z) => (z.bestellnummer ? `unserer Bestellung ${z.bestellnummer}${z.artikel ? ` (${z.artikel})` : ''}` : (z.artikel ?? 'Ihren Artikeln'));
const altPreis = (d) => ((d.alter_preis_gilt ?? []).length
  ? [`Für die bereits zum alten Preis bestätigten Bestellungen ${d.alter_preis_gilt.join(', ')} gilt der vereinbarte Preis.`] : []);

// Entwurf zur Preisentscheidung: bei einer AB zum bestätigten Preis, bei einer Mitteilung zur angekündigten Erhöhung
const preisEntwurf = (z, angenommen) => {
  const d = z.details ?? {};
  const ab = d.art === 'preis';
  const was = ab ? `den bestätigten Einzelpreis von ${zahl(d.bestaetigt)} ${d.waehrung} (bestellt war ${zahl(d.bestellt)} ${d.waehrung})`
    : `die angekündigte Preiserhöhung um ${d.prozent != null ? pz(d.prozent) : '[Prozent]'}${d.gueltig_ab ? ` ab ${datum(d.gueltig_ab)}` : ''}`;
  const einleitung = ab ? `vielen Dank für Ihre Auftragsbestätigung zu ${bezug(z)}.` : 'vielen Dank für Ihre Information zur Preisanpassung.';
  if (angenommen) {
    return lieferantEntwurf(z, 'preis_akzeptiert', `${ab ? `Bestellung ${z.bestellnummer}` : 'Preisanpassung'}: Preis bestätigt`,
      [einleitung, `${was.charAt(0).toUpperCase()}${was.slice(1)} akzeptieren wir${ab ? ' für diese Bestellung' : ''}.`, ...altPreis(d),
        'Künftige Preisänderungen kündigen Sie bitte mit Begründung und ausreichend Vorlauf an.']);
  }
  return lieferantEntwurf(z, 'preis_abgelehnt', `${ab ? `Bestellung ${z.bestellnummer}` : 'Preisanpassung'}: Preiserhöhung nicht akzeptiert`,
    [einleitung, `${was.charAt(0).toUpperCase()}${was.slice(1)} können wir so nicht akzeptieren.`,
      ab ? 'Bitte liefern Sie zum bestellten Preis oder senden Sie uns eine nachvollziehbare Kalkulation (Anteile Material, Energie, Lohn), damit wir die Erhöhung prüfen können.'
        : 'Bitte senden Sie uns eine nachvollziehbare Kalkulation (Anteile Material, Energie, Lohn). Bis zu einer Einigung gelten die vereinbarten Preise.',
      ...altPreis(d)]);
};

// Änderung am Produkt: Werkstoff und Abkündigung in einem Satz
const aenderung = (z) => {
  const a = z.abteilungen ?? {};
  const teile = [];
  if (a.werkstoff_alt || a.werkstoff_neu) teile.push(`Werkstoff ${a.werkstoff_alt ?? '[bisher]'} → ${a.werkstoff_neu ?? '[neu]'}`);
  if ((a.regel ?? []).includes('abkuendigung') || a.dispo) teile.push('Abkündigung bzw. nicht mehr verfügbar');
  return teile.length ? teile.join(', ') : 'Änderung am Produkt laut Mail';
};

// Abteilungen, an die der Einkauf weiterleiten kann: Aufgabe, Postfach und was sie prüfen sollen
const ABTEILUNGEN = {
  technik: { team: 'Technik', art: 'technik_freigabe', frage: 'Technik: Ist der neue Werkstoff bzw. die Abweichung zulässig? Braucht es eine Zeichnungsänderung?' },
  qm: { team: 'Qualitätsmanagement', art: 'qm_freigabe', frage: 'QM: Erstmusterprüfung bzw. Sonderfreigabe, Prüfumfang und benötigte Zeugnisse' },
  dispo: { team: 'Disposition', art: 'bestand_pruefen', frage: 'Disposition: Reichweite des Bestands, ist eine letzte Bestellung im bisherigen Stand nötig?' },
};
const NAME = { technik: 'Technik', qm: 'QM', dispo: 'Disposition' };
const internerEntwurf = (z, ziele, zweck) => {
  const a = z.abteilungen ?? {};
  const post = z.postfaecher ?? {};
  const empfaenger = ziele.map((x) => post[ABTEILUNGEN[x].team]).filter(Boolean);
  const text = ['Hallo zusammen,', '',
    `${z.lieferant_name ?? z.lieferant ?? 'Ein Lieferant'} meldet zu ${z.artikel ?? 'einem Artikel'}: ${aenderung(z)}.`, '',
    'Bitte prüft:', ...ziele.map((x) => `- ${ABTEILUNGEN[x].frage}`), '',
    `Bitte tragt eure Entscheidung in der Arbeitsliste ein (${ziele.map((x) => `"${ABTEILUNGEN[x].art === 'bestand_pruefen' ? 'Bestand und letzte Bestellung prüfen' : `${NAME[x]}-Freigabe`}"`).join(', ')}). Bis zur Freigabe von Technik und QM wird nichts umgestellt und keine Preiserhöhung freigegeben.`,
    ...(a.empfehlung ? ['', `Vorschlag des Modells, ungeprüft: ${a.empfehlung}`] : []), '',
    'Viele Grüße', z.einkaeufer ?? '[Name]', '', '----- Mail des Lieferanten -----', z.mailtext ?? '[Mailtext]'].join('\n');
  return { art: 'intern', zweck, empfaenger: empfaenger.join(', '), cc: null,
    betreff: `${ziele.length > 1 ? 'Freigabe erbeten' : `Bitte prüfen (${NAME[ziele[0]]})`}: ${aenderung(z)} – ${z.artikel ?? 'Artikel'} (${z.lieferant_name ?? z.lieferant ?? 'Lieferant'})`,
    text, warnungen: platzhalter(text) };
};
const abteilungsAufgabe = (z, x) => {
  const a = z.abteilungen ?? {};
  return { team: ABTEILUNGEN[x].team, zustaendig: null, art: ABTEILUNGEN[x].art, prioritaet: 'hoch',
    details: { lieferant: z.lieferant_name ?? z.lieferant, artikel: z.artikel, werkstoff_alt: a.werkstoff_alt ?? null,
      werkstoff_neu: a.werkstoff_neu ?? null, aenderung: aenderung(z), empfehlung: a.empfehlung ?? null } };
};
// Welche Freigaben vor der Preisfreigabe nötig sind: Technik bzw. QM, wenn Merker gesetzt oder schon eingebunden
const pflichtFreigaben = (a, aufg) => [['technik', 'technik_freigabe'], ['qm', 'qm_freigabe']]
  .filter(([m, art]) => a[m] || aufg.some((y) => y.art === art));

const ops = [];
const fehler = [];
const meldungen = [];
for (const z of zeilen) {
  const aufg = z.ticket_aufgaben ?? [];
  const zwecke = z.entwurf_zwecke ?? [];
  const op = { id: z.id, aktion: p.aktion, neue_aufgaben: [], entwuerfe: [] };
  const a = z.abteilungen ?? {};

  if (['freigegeben', 'abgelehnt'].includes(p.aktion) && !ENTSCHEIDBAR.includes(z.art)) { fehler.push('Freigeben und Ablehnen gibt es nur bei Preis-, Technik- und QM-Aufgaben.'); continue; }
  if (p.aktion === 'erledigt' && ENTSCHEIDBAR.includes(z.art)) { fehler.push('Diese Aufgabe braucht eine Entscheidung: Freigeben oder Ablehnen.'); continue; }

  // Ohne positive Freigabe von Technik und QM keine Preisfreigabe (die Datenbank prüft das beim Speichern noch einmal)
  if (p.aktion === 'freigegeben' && PREIS.includes(z.art)) {
    const fehlt = pflichtFreigaben(a, aufg).filter(([, art]) => !aufg.some((y) => y.art === art && y.entscheidung === 'freigegeben'));
    if (fehlt.length) {
      const eingebunden = fehlt.every(([, art]) => aufg.some((y) => y.art === art));
      fehler.push(eingebunden
        ? `Der Preis kann erst freigegeben werden, wenn ${fehlt.map(([m]) => NAME[m]).join(' und ')} freigegeben ${fehlt.length > 1 ? 'haben' : 'hat'}.`
        : `Die Mail betrifft eine Änderung am Produkt. Bitte zuerst an ${fehlt.map(([m]) => NAME[m]).join(' und ')} weiterleiten, der Preis kann erst nach deren Freigabe freigegeben werden.`);
      continue;
    }
  }

  if (p.aktion === 'einbinden' || p.aktion === 'weiterleiten') {
    // Einbinden: alle Abteilungen laut Merker (mindestens Technik und QM). Weiterleiten: genau eine.
    const gewuenscht = p.aktion === 'weiterleiten' ? [p.ziel] : ['technik', 'qm', ...(a.dispo ? ['dispo'] : [])];
    const ziele = gewuenscht.filter((x) => !aufg.some((y) => y.art === ABTEILUNGEN[x].art));
    if (!ziele.length) { fehler.push(`${gewuenscht.map((x) => NAME[x]).join(' und ')} ${gewuenscht.length > 1 ? 'sind' : 'ist'} für diesen Vorgang schon eingebunden.`); continue; }
    op.neue_aufgaben.push(...ziele.map((x) => abteilungsAufgabe(z, x)));
    op.entwuerfe.push(internerEntwurf(z, ziele, p.aktion === 'einbinden' ? 'abteilungen_einbinden' : `weiterleiten_${p.ziel}`));
    meldungen.push(`An ${ziele.map((x) => NAME[x]).join(', ')} weitergeleitet · interner Entwurf erstellt`);
  }

  if (p.aktion === 'unterlagen') {
    if (zwecke.includes('unterlagen_anfordern')) { fehler.push('Die Unterlagen sind für diesen Vorgang schon angefordert.'); continue; }
    op.entwuerfe.push(lieferantEntwurf(z, 'unterlagen_anfordern', `Änderung ${z.artikel ?? 'Artikel'}: Unterlagen und Erstmuster`, [
      `vielen Dank für Ihre Information zur Änderung bei ${z.artikel ?? 'dem Artikel'} (${aenderung(z)}).`,
      'Bevor wir zustimmen können, benötigen wir von Ihnen:\n- Datenblatt des neuen Werkstoffs\n- Werkstoffzeugnis 3.1 nach EN 10204\n- [Anzahl] Erstmuster mit Erstmusterprüfbericht\n- den Termin, ab dem Sie umstellen möchten',
      'Bis zu unserer schriftlichen Freigabe liefern Sie bitte weiterhin im bisherigen Werkstoff. Eine Umstellung ohne unsere Freigabe können wir nicht annehmen.',
      ...(a.dispo ? ['Bitte teilen Sie uns außerdem mit, bis wann und in welchen Mengen wir den bisherigen Artikel noch bestellen können.'] : []),
    ]));
    meldungen.push('Entwurf zur Anforderung von Unterlagen erstellt');
  }

  if (['freigegeben', 'abgelehnt'].includes(p.aktion) && PREIS.includes(z.art)) {
    // Zusage erst nach der letzten offenen Preisentscheidung im Vorgang, Absage sofort (aber nur einmal)
    const weitere = aufg.filter((y) => PREIS.includes(y.art) && y.status === 'offen' && y.id !== z.id);
    if (p.aktion === 'freigegeben' && !weitere.length && !zwecke.includes('preis_akzeptiert')) op.entwuerfe.push(preisEntwurf(z, true));
    if (p.aktion === 'abgelehnt' && !zwecke.includes('preis_abgelehnt')) op.entwuerfe.push(preisEntwurf(z, false));
    // Meldung für den Hinweis nach der Aktion: Eine Freigabe akzeptiert Mehrkosten, nur eine Ablehnung vermeidet Kosten
    const jahr = Number((z.details ?? {}).jahres_mehrkosten_eur ?? 0);
    const betrag = `${Math.round(jahr).toLocaleString('de-DE')} €`;
    meldungen.push(p.aktion === 'freigegeben'
      ? `Freigegeben${jahr ? ` · Mehrkosten ${betrag} pro Jahr akzeptiert` : ''}${op.entwuerfe.length ? ' · Entwurf an Lieferant erstellt' : ''}`
      : `Abgelehnt${jahr ? ` · ${betrag} Cost Avoidance vorgemerkt` : ''}${op.entwuerfe.length ? ' · Entwurf an Lieferant erstellt' : ''}`);
  }
  ops.push(op);
}

if (!ops.length) return [{ json: { zulaessig: false, fehler: [...new Set(fehler)] } }];
if (!meldungen.length) meldungen.push(p.sammel ? `${ops.length} Preisfreigaben erteilt` : (p.aktion === 'erledigt' ? 'Erledigt' : 'Gespeichert'));
if (p.sammel) meldungen.splice(0, meldungen.length, `${ops.length} unkritische Preisfreigaben erteilt · Entwürfe an Lieferanten erstellt`);
// Rücksprung mit kurzer Meldung (die Arbeitsliste zeigt sie escaped als Hinweis unten rechts)
const meldung = [...new Set(meldungen)].join(' | ').slice(0, 200);
return [{ json: { zulaessig: true, ops, akteur: p.akteur, notiz: p.notiz, sammel: p.sammel, meldung } }];
